32	 * stays inside the painted 05 tunnel. The far block folded away while the eye was still 10 … 6.5 u from its capped
33	 * seam (s ≈ 186.5), so for the last ≈ 5 u of the stage the camera looked into the old generic 06 hall (white foam
34	 * walls, flat pink) instead of the 05 rings / slotted walls / S-river. Now it folds only once Benny reaches the seam
35	 * (eye → seam 6.8 … 5.2 u: Benny ≈ 187.6 … 189, done as Benny enters 06): until then the same world-anchored 05 block (rings, walls, far river,
36	 * warm throat) continues ahead — faithful continuation of the painted tunnel, nothing new. Geometry, course and the
37	 * 06 look unchanged; the locked view never uses this (block at its build-time geometry there).
38	 */
39	export const M05END: boolean = M05FAR && flag05('m05end');
40	/**
41	 * `&m05fcoin=1` (Screen 05 round 12, needs m05far; src/gameplay/coins.ts): coin LOOK only. Past the far seam the real
42	 * course climbs away toward 06 while the far block shows the painted 05 river running on into the throat, so the next
43	 * coins (06) floated over the far block's left wall (t90 / t95). While the block is live, a coin past the seam is drawn
44	 * where the far block shows that stretch of river: on the far river's cyan core at virtual depth Z = s − sF, scaled like
45	 * the block (kOf), facing down the tunnel; as the block folds into 06 it moves back to its real place. Positions,
46	 * pickups, count and score unchanged. `far05Coins` is written by the live sync below.
47	 */
48	export const M05FCOIN: boolean = M05FAR && flag05('m05fcoin');
49	export const far05Coins = {
50	  /** 1 while the far block is live (not at the locked eye, not fully folded) */
51	  live: 0,
52	  /** course s of the sliding seam */
53	  seamS: 0,
54	  /** fold factor 0 … 1 */
55	  open: 1,
56	  /** tunnel axis (coins face down it) */
57	  T: new THREE.Vector3(0, 0, 1),
58	  /** visual place of a coin at course s, lateral offset dl from the core, height h above the water: writes `out`,
59	   *  returns the block's scale there (0 = beyond the throat) */
60	  map: null as null | ((s: number, dl: number, h: number, out: THREE.Vector3) => number),
61	};
62	
63	type Item = { u: number; o: THREE.Vector3; basis: THREE.Matrix4; s: THREE.Vector3; openPos: THREE.Vector3; openScale: number };
64	
65	export interface LiveFar05Args {
66	  ft: ForcedTunnel;
67	  farWall: THREE.Mesh;
68	  farRiver: THREE.Mesh;
69	  farRings: THREE.InstancedMesh;
70	  farLids: THREE.InstancedMesh;
71	  ringItems: Item[];
72	  lidItems: Item[];
73	  glow: THREE.Mesh;
74	  glowMat: THREE.ShaderMaterial;
75	  lay: FarRiverLayout;
76	  level: number;
77	  zEnd: number;
78	  warp?: TubeWarp;
79	  /** wall build parameters (as ft.geometry(radial, steps, inset)) */
80	  radial: number; wallSteps: number; inset: number;
81	  /** river build parameters (as farRiverGeometry(cols, steps)) */
82	  cols: number; riverSteps: number;
83	  /** largest real extension beyond sF05 (units) */
84	  zCap: number;
85	  /** fold window: eye → seam distance (units) */
86	  foldNear: number; foldFar: number;
87	  /** the real course's height above the axis at real distance z beyond sF05 (the far water meets it at the seam) */
88	  riverUp: (z: number) => number;
89	  /** `&m05blend=1` (round 9): the real course (the far river's first rows are laid onto the ribbon's surface at the seam) */
90	  course?: Course;
91	  /** `&m05fcloud=1` (round 12): foam-cloud lumps along both far banks (src/vfx/foam.ts createFarCloud05) */
92	  clouds?: { mesh: THREE.InstancedMesh; lumps: FarLump05[] };
93	}
94	
95	const ROW_KEYS: (keyof FarRiverRow)[] = ['xB', 'hw', 'cL', 'wL', 'cR', 'wR', 'core'];
96	
97	/** returns sync(cam): call from every far part's onBeforeRender */
98	export function createLiveFar05(a: LiveFar05Args): (cam: THREE.Camera) => void {
99	  const { ft } = a;
100	  const L = ft.L, c0 = ft.c0, T = ft.T, U = ft.U, Rt = ft.Rt, R = ft.R, sF = ft.sF;
101	  const D0lock = ft.D0;
102	  // the river layout depends on Z only: tabulate it once (dense near the seam) and interpolate
103	  const NT = 2400;
104	  const tz = new Float64Array(NT + 1), tr = new Float64Array((NT + 1) * ROW_KEYS.length);
105	  for (let n = 0; n <= NT; n++) {
106	    const Z = a.zEnd * (n / NT) ** 2;
107	    tz[n] = Z;
108	    const r = a.lay.row(Z);
109	    ROW_KEYS.forEach((k, i) => { tr[n * ROW_KEYS.length + i] = r[k]; });
110	  }
111	  const rowAt = (Z: number): FarRiverRow => {
112	    const f = Math.sqrt(Math.min(1, Math.max(0, Z / a.zEnd))) * NT;
113	    const n = Math.min(NT - 1, Math.floor(f)), w = f - n;
114	    const o = {} as FarRiverRow;
115	    ROW_KEYS.forEach((k, i) => { o[k] = tr[n * ROW_KEYS.length + i] * (1 - w) + tr[(n + 1) * ROW_KEYS.length + i] * w; });
116	    return o;
117	  };
118	
119	  // live state
120	  let D0 = D0lock, zs = 0;
121	  const q = new THREE.Vector3();
122	  const zOf = (Z: number) => (Z <= zs ? Z : zs + (Z - zs) / (1 + (Z - zs) / L));
123	  const kOf = (Z: number) => (D0 + zOf(Z)) / (D0 + Z);
124	  const cOf = (Z: number) => { if (Z <= zs) return 1; const b = 1 + (Z - zs) / L; return 1 / (b * b); };
125	  const tmp = new THREE.Vector3();
126	  const point = (Z: number, o: THREE.Vector3, out: THREE.Vector3) => {
127	    const k = kOf(Z);
128	    return out.copy(c0).addScaledVector(T, zOf(Z)).add(q).addScaledVector(tmp.copy(o).sub(q), k);
129	  };
130	
131	  // originals, restored whenever the eye is back at the locked checkpoint eye (the locked view stays bit-identical)
132	  const wg = a.farWall.geometry, rg = a.farRiver.geometry;
133	  const keep = (g: THREE.BufferGeometry, names: string[]) => names.map((n) => (g.getAttribute(n).array as Float32Array).slice());
134	  const wallNames = ['position', 'uv', 'fgExtra'];
135	  const wallOrig = keep(wg, wallNames);
136	  const wallOpenOrig = (wg.morphAttributes.position[0].array as Float32Array).slice();
137	  const rivNames = ['position', 'uv', 'aRivLat', 'aRivA', 'aRivB', 'fgExtra'];
138	  const rivOrig = keep(rg, rivNames);
139	  const rivOpenOrig = (rg.morphAttributes.position[0].array as Float32Array).slice();
140	  const eyeLock = c0.clone().addScaledVector(T, -D0lock).add(ft.q);
141	  m05eye.value.set(eyeLock.x, eyeLock.y, eyeLock.z, 1);   // `&m05wall=1` (round 9): crisp walls only away from this eye
142	  const glowPos0 = a.glow.position.clone(), glowScale0 = a.glow.scale.x;
143	
144	  const restore = () => {
145	    wallNames.forEach((n, i) => { (wg.getAttribute(n).array as Float32Array).set(wallOrig[i]); wg.getAttribute(n).needsUpdate = true; });
146	    (wg.morphAttributes.position[0].array as Float32Array).set(wallOpenOrig); wg.morphAttributes.position[0].needsUpdate = true;
147	    rivNames.forEach((n, i) => { (rg.getAttribute(n).array as Float32Array).set(rivOrig[i]); rg.getAttribute(n).needsUpdate = true; });
148	    (rg.morphAttributes.position[0].array as Float32Array).set(rivOpenOrig); rg.morphAttributes.position[0].needsUpdate = true;
149	    a.glow.position.copy(glowPos0); a.glow.scale.setScalar(glowScale0);
150	  };
151	
152	  const d = new THREE.Vector3(), o = new THREE.Vector3(), p = new THREE.Vector3(), cr = new THREE.Vector3();
153	  const wv = new THREE.Vector2();
154	  // `&m05blend=1` (round 9): the far river's first rows are laid onto the near ribbon's surface (course frame + trough +
155	  // the ribbon's own vertex wave) so the two surfaces meet without a step at the seam (measured at t66 before: the far
156	  // row stood 0.36 u above the ribbon on the left and 0.31 u below it on the right — the course banks there, the far
157	  // river is level in the tunnel frame)
158	  const HB = 3;
159	  const cs: CourseSample = { s: 0, pos: new THREE.Vector3(), tan: new THREE.Vector3(), up: new THREE.Vector3(), right: new THREE.Vector3() };
160	  const tq = new THREE.Vector3();
161	  const onRibbon = (P: THREE.Vector3, sGuess: number, w: number) => {
162	    const course = a.course!;
163	    let sR = sGuess;
164	    for (let it = 0; it < 3; it++) { course.sample(sR, cs); sR += tq.copy(P).sub(cs.pos).dot(cs.tan); }
165	    course.sample(sR, cs);
166	    const hwR = course.widthAt(sR) / 2;
167	    const lat = tq.copy(P).sub(cs.pos).dot(cs.right);
168	    const uu = Math.min(1, Math.abs(lat) / hwR);
169	    const t = (m05blendTime.u?.value as number | undefined) ?? 0, uS = Math.max(-1, Math.min(1, lat / hwR));
170	    const hR = EDGE_LIFT * uu * uu * uu + ampAt(course, sR) * (0.6 * Math.sin(sR * 0.9 - t * 2.4 + uS * 1.7) + 0.4 * Math.sin(sR * 0.41 + t * 1.5 - uS * 2.3));
171	    tq.copy(cs.pos).addScaledVector(cs.right, lat).addScaledVector(cs.up, hR).sub(P);
172	    // outside the ribbon (its skirt drops away) the far bank keeps its own height
173	    const wl = w * (1 - THREE.MathUtils.smoothstep(Math.abs(lat), hwR, hwR + 0.8));
174	    P.addScaledVector(U, tq.dot(U) * wl);
175	  };
176	  const rowZ = (i: number, steps: number, zFrom: number) => {
177	    // uniform in projected radius (1/D), as ForcedTunnel.geometry
178	    const t = i / steps, Da = D0 + zFrom;
179	    const Dv = 1 / (1 / Da - t * (1 / Da - 1 / (D0 + a.zEnd)));
180	    return Math.max(zFrom, Dv - D0);
181	  };
182	  const fillWall = () => {
183	    const pos = wg.getAttribute('position').array as Float32Array, uv = wg.getAttribute('uv').array as Float32Array;
184	    const ext = wg.getAttribute('fgExtra').array as Float32Array, opn = wg.morphAttributes.position[0].array as Float32Array;
185	    const r0 = R * (1 - a.inset);
186	    for (let i = 0; i <= a.wallSteps; i++) {
187	      const Z = rowZ(i, a.wallSteps, 0), z = zOf(Z), sReal = sF + z;
188	      const fr = ft.path.frame(sReal);
189	      tubeCenterAt(ft.path, sReal, cr);
190	      const rOpen = ft.path.radius(sReal) * 1.1 + 0.4;
191	      const vv = sF + ft.uOfZ(Z);
192	      for (let j = 0; j <= a.radial; j++) {
193	        const th = -1.5 * Math.PI + (j / a.radial) * Math.PI * 2;
194	        d.copy(Rt).multiplyScalar(Math.cos(th)).addScaledVector(U, Math.sin(th));
195	        o.copy(d).multiplyScalar(r0);
196	        if (a.warp) { a.warp(Z, th, wv); o.addScaledVector(Rt, wv.x).addScaledVector(U, wv.y); }
197	        point(Z, o, p);
198	        const k = i * (a.radial + 1) + j;
199	        p.toArray(pos, k * 3);
200	        uv[k * 2 + 1] = vv;
201	        ext[k] = Z - z;
202	        o.copy(fr.right).multiplyScalar(Math.cos(th)).addScaledVector(fr.up, Math.sin(th)).multiplyScalar(rOpen).add(cr);
203	        o.toArray(opn, k * 3);
204	      }
205	    }
206	    for (const n of wallNames) wg.getAttribute(n).needsUpdate = true;
207	    wg.morphAttributes.position[0].needsUpdate = true;
208	  };
209	  const fillRiver = () => {
210	    const pos = rg.getAttribute('position').array as Float32Array, uv = rg.getAttribute('uv').array as Float32Array;
211	    const lat = rg.getAttribute('aRivLat').array as Float32Array, A = rg.getAttribute('aRivA').array as Float32Array;
212	    const B = rg.getAttribute('aRivB').array as Float32Array, ext = rg.getAttribute('fgExtra').array as Float32Array;
213	    const opn = rg.morphAttributes.position[0].array as Float32Array;
214	    const bank = 3, per = a.cols + 1 + 2 * bank, ch = a.lay.chord;
215	    for (let i = 0; i <= a.riverSteps; i++) {
216	      // the far river starts AT the seam: before it the real ribbon carries the course
217	      const Z = rowZ(i, a.riverSteps, zs), z = zOf(Z), sReal = sF + z;
218	      const fr = ft.path.frame(sReal);
219	      tubeCenterAt(ft.path, sReal, cr);
220	      const rr = ft.path.radius(sReal);
221	      const r = rowAt(Z);
222	      // lift to the real river where the seam has slid (the real ribbon starts climbing toward 06 there): 0 at zs = 0
223	      const lift = zs > 0 ? a.riverUp(Math.min(Z, zs)) - a.riverUp(0) : 0;
224	      const e0 = Math.max(-ch + 0.05, r.xB - r.hw), e1 = Math.min(ch - 0.05, r.xB + r.hw);
225	      const vv = sF + ft.uOfZ(Z);
226	      for (let j = 0; j < per; j++) {
227	        let x: number, h: number;
228	        if (j < bank) { const f = j / bank; x = -ch + (e0 + ch) * f; h = EDGE_LIFT + 0.1 * Math.sin(Math.PI * f); }
229	        else if (j > bank + a.cols) { const f = (j - bank - a.cols) / bank; x = e1 + (ch - e1) * f; h = EDGE_LIFT + 0.1 * Math.sin(Math.PI * f); }
230	        else {
231	          const f = (j - bank) / a.cols; x = e0 + (e1 - e0) * f;
232	          const u = Math.min(1, Math.abs(x - r.xB) / Math.max(0.5, r.hw));
233	          h = EDGE_LIFT * u * u * u;
234	        }
235	        o.copy(Rt).multiplyScalar(x).addScaledVector(U, a.level + h + lift);
236	        point(Z, o, p);
237	        if (M05BLEND && a.course && zs > 0 && Z < zs + HB) onRibbon(p, sReal, 1 - THREE.MathUtils.smoothstep(Z, zs, zs + HB));
238	        const k = i * per + j;
239	        p.toArray(pos, k * 3);
240	        uv[k * 2] = (x + ch) / (2 * ch); uv[k * 2 + 1] = vv;
241	        lat[k] = x;
242	        A[k * 4] = r.xB; A[k * 4 + 1] = r.hw; A[k * 4 + 2] = r.cL; A[k * 4 + 3] = r.cR;
243	        B[k * 4] = r.wL; B[k * 4 + 1] = r.wR; B[k * 4 + 2] = r.core; B[k * 4 + 3] = Z;
244	        ext[k] = Z - z;
245	        o.copy(cr).addScaledVector(fr.right, x * (rr / R)).addScaledVector(fr.up, -rr - 0.6);
246	        o.toArray(opn, k * 3);
247	      }
248	    }
249	    for (const n of rivNames) rg.getAttribute(n).needsUpdate = true;
250	    rg.morphAttributes.position[0].needsUpdate = true;
251	  };
252	  const m = new THREE.Matrix4(), A4 = new THREE.Matrix4(), S4 = new THREE.Matrix4();
253	  const place = (mesh: THREE.InstancedMesh, items: Item[], open: number) => {
254	    const ext = mesh.geometry.getAttribute('fgExtra') as THREE.InstancedBufferAttribute | undefined;
255	    items.forEach((it, i) => {
256	      const Z = ft.zOfU(it.u);
257	      const k = THREE.MathUtils.lerp(kOf(Z), it.openScale, open);
258	      const c = THREE.MathUtils.lerp(cOf(Z), 1, open);
259	      point(Z, it.o, p).lerp(it.openPos, open);
260	      A4.set(
261	        k + (c - k) * T.x * T.x, (c - k) * T.x * T.y, (c - k) * T.x * T.z, 0,
262	        (c - k) * T.y * T.x, k + (c - k) * T.y * T.y, (c - k) * T.y * T.z, 0,
263	        (c - k) * T.z * T.x, (c - k) * T.z * T.y, k + (c - k) * T.z * T.z, 0,
264	        0, 0, 0, 1,
265	      );
266	      m.copy(A4).multiply(it.basis).multiply(S4.makeScale(it.s.x, it.s.y, it.s.z)).setPosition(p);
267	      mesh.setMatrixAt(i, m);
268	      ext?.setX(i, (Z - zOf(Z)) * (1 - open));
269	    });
270	    mesh.instanceMatrix.needsUpdate = true;
271	    if (ext) ext.needsUpdate = true;
272	  };
273	
274	  let lastEye = new THREE.Vector3(Infinity, 0, 0), live = true, open = 0;
275	  const eye = new THREE.Vector3();
276	  // `&m05fcloud=1` (Screen 05 round 12): far-bank foam clouds on the far layout's water edge, anchored to the virtual
277	  // tunnel, compressed like the block, only where the block is live and its baked picture magnified (as m05fmag)
278	  const cm = new THREE.Matrix4(), cp = new THREE.Vector3(), co = new THREE.Vector3();
279	  // `&m05fcoin=1` (Screen 05 round 12): a coin's visual place on the far river's core (see M05FCOIN)
280	  const fco = new THREE.Vector3();
281	  if (M05FCOIN) {
282	    far05Coins.map = (s: number, dl: number, h: number, out: THREE.Vector3) => {
283	      const Z = s - sF;
284	      if (Z > a.zEnd * 0.98) return 0;
285	      const r = rowAt(Z);
286	      const lift0 = zs > 0 ? a.riverUp(Math.min(Z, zs)) - a.riverUp(0) : 0;
287	      fco.copy(Rt).multiplyScalar(THREE.MathUtils.clamp(r.core + dl, r.cL, r.cR)).addScaledVector(U, a.level + lift0 + h);
288	      point(Z, fco, out);
289	      return kOf(Z);
290	    };
291	  }
292	  const placeClouds = (show: boolean) => {
293	    const c = a.clouds;
294	    if (!c) return;
295	    c.mesh.visible = show;
296	    if (!show) return;
297	    const lift0 = zs > 0 ? a.riverUp(zs) - a.riverUp(0) : 0;
298	    const ch = a.lay.chord - 0.1;
299	    c.lumps.forEach((l, i) => {
300	      let sc = 0;
301	      if (l.Z > zs + 0.02) {
302	        const r = rowAt(l.Z);
303	        const x = THREE.MathUtils.clamp(l.side < 0 ? r.xB - r.hw - l.e : r.xB + r.hw + l.e, -ch, ch);
304	        co.copy(Rt).multiplyScalar(x).addScaledVector(U, a.level + EDGE_LIFT + lift0 + l.lift);
305	        point(l.Z, co, cp);
306	        const mag = (D0lock + l.Z) / Math.max(cp.distanceTo(eye), 0.5);
307	        sc = l.r * kOf(l.Z) * THREE.MathUtils.smoothstep(mag, 1.4, 2.2) * THREE.MathUtils.smoothstep(l.Z, zs, zs + 0.6) * (1 - open);
308	      }
309	      c.mesh.setMatrixAt(i, cm.makeScale(sc, sc, sc).setPosition(cp));
310	    });
311	    c.mesh.instanceMatrix.needsUpdate = true;
312	  };
313	  return (cam: THREE.Camera) => {
314	    eye.setFromMatrixPosition(cam.matrixWorld);
315	    if (eye.distanceToSquared(lastEye) < 1e-10) return;
316	    lastEye.copy(eye);
317	    const atLock = eye.distanceTo(eyeLock) < 2e-3;
318	    D0 = Math.max(0.5, c0.clone().sub(eye).dot(T));
319	    q.copy(eye).sub(c0).addScaledVector(T, c0.clone().sub(eye).dot(T));
320	    zs = Math.min(a.zCap, Math.max(0, D0lock - D0));
321	    if (zs < 1e-6) zs = 0;
322	    // m05end (r11): the TRUE eye → seam distance (D0 is clamped at 0.5 u once the eye passes sF, so D0 + zs never fell
323	    // under 0.5 + zCap ≈ 7 u and the block could not fold inside a window nearer than that)
324	    open = 1 - THREE.MathUtils.smoothstep(M05END ? c0.clone().sub(eye).dot(T) + zs : D0 + zs, a.foldNear, a.foldFar);
325	    if (atLock) {
326	      // the locked checkpoint eye: the build-time geometry (bit-identical locked view)
327	      if (live) { restore(); live = false; }
328	      D0 = D0lock; q.copy(ft.q); zs = 0; open = 0;
329	      ft.placeInstances(a.farRings, a.ringItems, 0);
330	      ft.placeInstances(a.farLids, a.lidItems, 0);
331	    } else {
332	      fillWall(); fillRiver();
333	      a.glow.position.copy(point(a.zEnd, o.set(0, 0, 0), p));
334	      a.glow.scale.setScalar(R * kOf(a.zEnd) * 1.35);
335	      live = true;
336	      place(a.farRings, a.ringItems, open);
337	      place(a.farLids, a.lidItems, open);
338	    }
339	    placeClouds(!atLock && open < 0.999);
340	    if (M05FCOIN) {
341	      far05Coins.live = !atLock && open < 0.999 ? 1 : 0;
342	      far05Coins.seamS = sF + zs;
343	      far05Coins.open = open;
344	      far05Coins.T.copy(T);
345	    }
346	    // foam behind the seam (the rising 06 banks) is clipped while the block is live (src/vfx/clip05.ts)
347	    if (atLock || open > 0.5) clip05.uClip05N.value.set(0, 0, 0);
348	    else { clip05.uClip05P.value.copy(c0).addScaledVector(T, zs); clip05.uClip05N.value.copy(T); }
349	    // `&m05seam=1` (Screen 05 round 8): the seam's course position for the near river's design hand-over (waterRibbon.ts)
350	    m05seam.value.set(sF + zs, atLock || open > 0.5 ? 0 : 1);
351	    if (M05BLEND) {
352	      // `&m05blend=1` (Screen 05 round 9): the near ribbon fades into the far river's picture over a band before the
353	      // seam (waterRibbon.ts M05BLEND). Band ≈ a quarter of the eye → seam distance (2.5–8 u), never before sF (F has no
354	      // rows there); off at the locked eye and while folding
355	      m05blend.uFbC0.value.copy(c0); m05blend.uFbT.value.copy(T); m05blend.uFbRt.value.copy(Rt);
356	      const band = Math.min(zs, THREE.MathUtils.clamp(0.25 * (D0 + zs), 2.5, 8));
357	      m05blend.uFbP.value.set(zs, band, a.lay.chord, atLock || open > 0.5 ? 0 : 1);
358	    }
359	    a.farWall.morphTargetInfluences![0] = open;
360	    a.farRiver.morphTargetInfluences![0] = open;
361	    a.glowMat.uniforms.uOpacity.value = 1 - open;
362	  };
363	}
